#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; este wizard te dice exactamente qué hacer y\n' "$DIM"
  printf '  captura los valores que copies. Para en cualquier momento con Ctrl-C\n'
  printf '  y vuelve a correrlo, recuerda los valores ya guardados.%s\n' "$RESET"
  pause "¿Listo para empezar?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Etapa %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ abriendo%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "no pude abrir el navegador; visita manualmente: $url"; fi
  } >/dev/null 2>&1 || warn "no pude abrir el navegador; visita manualmente: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Presiona Enter para continuar}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [s/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[SsYy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter mantiene el valor actual]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter mantiene el valor actual]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ guardado%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name")
  warn "omitido: $name"
}

set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "omitido: $name"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Configuración completa%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "guardados ${#WRITTEN_ENV[@]} valor(es) en $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "secrets configurados: ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "pendiente por hacer manualmente:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: pasos para crear un Personal Access Token en GitLab
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

banner "GitLab Personal Access Token — VeterinariaAPK"

# ── Etapa 1: Iniciar sesión ───────────────────────────────────────────────
stage "Inicia sesión en GitLab"
say "Abriendo GitLab. Si ya tienes sesión activa, salta al siguiente paso."
open_url "https://gitlab.com/users/sign_in"
step "Ingresa tu usuario y contraseña de GitLab."
step "Completa el 2FA si te lo solicita."
pause "Presiona Enter una vez hayas iniciado sesión."

# ── Etapa 2: Ir a Access Tokens ──────────────────────────────────────────
stage "Navegar a Personal Access Tokens"
say "Abriendo la página de tokens de acceso personal."
open_url "https://gitlab.com/-/user_settings/personal_access_tokens"
step "Deberías ver la pantalla 'Personal access tokens'."
step "Si GitLab te redirige al inicio de sesión, vuelve a la Etapa 1."
pause "Presiona Enter cuando estés en la página de tokens."

# ── Etapa 3: Crear el token ───────────────────────────────────────────────
stage "Crear el token con los permisos necesarios"
say "Ahora crearás un token con acceso a la API y al repositorio."
say ""
step "Haz clic en 'Add new token'."
step "En 'Token name' escribe:  VeterinariaAPK-claude"
step "En 'Expiration date' elige una fecha (p.ej. 90 días desde hoy)."
step "Marca EXACTAMENTE estos scopes (casillas):"
note "    ☑  api"
note "    ☑  read_repository"
note "    ☑  write_repository"
step "Haz clic en 'Create personal access token'."
warn "El token se muestra UNA SOLA VEZ. Cópialo antes de salir de la página."
pause "Presiona Enter cuando el token ya aparezca en pantalla."

# ── Etapa 4: Guardar el token ─────────────────────────────────────────────
stage "Guardar el token"
say "Pega el token aquí. No se mostrará mientras escribes (campo oculto)."
say ""
ask_secret GITLAB_TOKEN "Token de GitLab (glpat-...):"

if [[ -z "$GITLAB_TOKEN" ]]; then
  warn "No pegaste ningún token. Vuelve a correr el script cuando lo tengas."
  exit 1
fi

# Validación básica: los tokens de GitLab empiezan con glpat-
if [[ "$GITLAB_TOKEN" != glpat-* ]]; then
  warn "El token no tiene el formato esperado (glpat-...). Verifica que copiaste todo."
  confirm "¿Quieres guardarlo de todas formas?" || exit 1
fi

write_env GITLAB_TOKEN "$GITLAB_TOKEN"
write_env GITLAB_PROJECT_URL "https://gitlab.com/aunar-group1/VeterinariaAPK"

say ""
note "Token guardado en .env — el agente lo usará para crear ramas e issues."

finish
